
"use client";

import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger, SheetFooter } from "@/components/ui/sheet";
import { useAppContext } from "@/context/app-context";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Trash2, ShoppingBasket } from "lucide-react";
import Image from "next/image";

export function CartSheet({ children }: { children: React.ReactNode }) {
  const { cart, removeFromCart, clearCart } = useAppContext();
  const totalPrice = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);

  return (
    <Sheet>
      <SheetTrigger asChild>
        {children}
      </SheetTrigger>
      <SheetContent className="w-full sm:max-w-md flex flex-col bg-background">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-2">
            <ShoppingBasket className="h-5 w-5 text-primary" />
            Your Shopping Bag
          </SheetTitle>
        </SheetHeader>

        <div className="flex-1 overflow-hidden py-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-muted-foreground gap-4">
              <ShoppingBasket className="h-12 w-12 opacity-20" />
              <p>Your bag is empty. Time for some cake?</p>
            </div>
          ) : (
            <ScrollArea className="h-full pr-4">
              <div className="space-y-4">
                {cart.map((item) => (
                  <div key={item.id} className="flex gap-4 items-center animate-pop-in">
                    <div className="relative h-16 w-16 overflow-hidden rounded-md border">
                      <Image 
                        src={item.imageUrl} 
                        alt={item.name} 
                        fill 
                        className="object-cover"
                      />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-semibold truncate">{item.name}</h4>
                      <p className="text-xs text-muted-foreground">Qty: {item.quantity}</p>
                      <p className="text-sm font-medium text-primary">${(item.price * item.quantity).toFixed(2)}</p>
                    </div>
                    <Button 
                      variant="ghost" 
                      size="icon" 
                      className="h-8 w-8 text-muted-foreground hover:text-destructive transition-colors"
                      onClick={() => removeFromCart(item.id)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                ))}
              </div>
            </ScrollArea>
          )}
        </div>

        {cart.length > 0 && (
          <SheetFooter className="flex-col sm:flex-col gap-4 border-t pt-4">
            <div className="flex justify-between items-center w-full">
              <span className="text-lg font-bold">Total</span>
              <span className="text-2xl font-black text-primary">${totalPrice.toFixed(2)}</span>
            </div>
            <div className="grid grid-cols-2 gap-2 w-full">
              <Button variant="outline" onClick={clearCart}>Clear All</Button>
              <Button className="bg-primary text-primary-foreground hover:bg-primary/90">Checkout</Button>
            </div>
          </SheetFooter>
        )}
      </SheetContent>
    </Sheet>
  );
}
