
"use client";

import { useState } from 'react';
import { Sparkles, Loader2, CakeSlice } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { getAICakeSuggestions, AICakeSuggestionOutput } from '@/ai/flows/ai-cake-suggestion-flow';
import { useAppContext } from '@/context/app-context';
import { Badge } from '@/components/ui/badge';

export function AICakeSuggestions() {
  const { cart, user } = useAppContext();
  const [loading, setLoading] = useState(false);
  const [suggestions, setSuggestions] = useState<AICakeSuggestionOutput['suggestions'] | null>(null);

  const fetchSuggestions = async () => {
    setLoading(true);
    try {
      // Basic input derived from mock user context or trends
      const pastHistory = cart.map(item => item.name);
      const result = await getAICakeSuggestions({
        currentTrends: "floral designs, pastel color palettes, citrus flavors, and multi-layered mini cakes",
        pastOrderHistory: pastHistory.length > 0 ? pastHistory : ["Strawberry Vanilla", "Chocolate Mousse"]
      });
      setSuggestions(result.suggestions);
    } catch (error) {
      console.error("AI Suggestion Error:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section className="py-12 px-4 bg-secondary/30 rounded-3xl my-12">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-8">
          <Badge variant="secondary" className="mb-2 bg-primary/20 text-primary-foreground border-primary/20">
            AI Powered
          </Badge>
          <h2 className="text-3xl font-bold mb-4 flex items-center justify-center gap-2">
            <Sparkles className="h-6 w-6 text-primary" />
            Personalized Cake Sommelier
          </h2>
          <p className="text-muted-foreground">
            Let our AI recommend the perfect cake based on your taste and current trends.
          </p>
        </div>

        <div className="flex justify-center mb-10">
          <Button 
            onClick={fetchSuggestions} 
            disabled={loading}
            className="bg-primary text-primary-foreground hover:bg-primary/90 px-8 py-6 text-lg rounded-full shadow-lg transition-all hover:scale-105"
          >
            {loading ? (
              <>
                <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                Baking Ideas...
              </>
            ) : (
              <>
                <Sparkles className="mr-2 h-5 w-5" />
                Find My Perfect Slice
              </>
            )}
          </Button>
        </div>

        {suggestions && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-pop-in">
            {suggestions.map((s, idx) => (
              <Card key={idx} className="border-none shadow-md hover:shadow-lg transition-shadow bg-background/80 backdrop-blur-sm overflow-hidden group">
                <CardHeader className="bg-primary/5 pb-2">
                  <div className="flex items-center gap-2 text-primary">
                    <CakeSlice className="h-5 w-5" />
                    <CardTitle className="text-xl group-hover:translate-x-1 transition-transform">{s.flavor}</CardTitle>
                  </div>
                </CardHeader>
                <CardContent className="pt-4">
                  <p className="text-sm leading-relaxed text-muted-foreground italic">
                    "{s.design}"
                  </p>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}
